import{_ as a,c as n,ap as o,o as l}from"./chunks/framework.CCxIPCIe.js";const u=JSON.parse('{"title":"语音处理的数据集管理与 Lhotse 介绍","description":"","frontmatter":{"title":"语音处理的数据集管理与 Lhotse 介绍","date":"2026-09-09T13:01:36.874Z","length":"2438字","time":"9分钟","aside":true,"hash":1676875647},"headers":[],"relativePath":"note/编程/语音处理的数据集.md","filePath":"note/编程/语音处理的数据集.md"}'),p={name:"note/编程/语音处理的数据集.md"};function e(t,s,c,r,y,i){return l(),n("div",null,s[0]||(s[0]=[o(`<h2 id="引入" tabindex="-1">引入 <a class="header-anchor" href="#引入" aria-label="Permalink to &quot;引入&quot;">​</a></h2><p>每次做语音处理的项目时，总会遇到数据集如何处理的问题。今天试着总结一下。</p><p>我们先假设数据集是干净的，即不考虑数据集的清洗问题。对于语音数据集我们一般需要考虑以下几件事：</p><ol><li>读取：把波形文件或其他格式的文件读取为 numpy 数组，进而转换成 torch 张量。</li><li>重采样：把不同采样率的音频文件统一到使用采样率。</li><li>分段：每次取一小片分段。</li><li>补零：对不满足固定长度的音频片段进行补零，保证每个批次的张量形状一致。</li><li>增强：对音频片段进行增强，例如加噪、加混响等。</li><li>混合：对不同数据集进行混合采样，保证数据的多样性和均衡性。</li></ol><h3 id="读取" tabindex="-1">读取 <a class="header-anchor" href="#读取" aria-label="Permalink to &quot;读取&quot;">​</a></h3><p>我们先忽略 <a href="./深度学习的数据集加载问题">深度学习的数据集加载问题</a> 中提到的加载速度问题，先假设数据集总是以 <code>.wav</code> 文件的形式存在于硬盘上，且不考虑缓存进内存的情况。因此我们实际上只需要保存一个文件路径列表懒加载。只有真正到<code>__getitem__</code>的时候才读取文件。</p><h3 id="分段" tabindex="-1">分段 <a class="header-anchor" href="#分段" aria-label="Permalink to &quot;分段&quot;">​</a></h3><p>soundfile 支持在读取 wav 时直接指定起始和结束位置来实现分段，这样就节省了读取整个音频文件再切片的开销，如果我们不缓存音频文件的话，在读取时就分段是最优的选择。如果我们缓存了音频文件，那么也许先读取整个音频文件再切片可能更合适。</p><h3 id="补零" tabindex="-1">补零 <a class="header-anchor" href="#补零" aria-label="Permalink to &quot;补零&quot;">​</a></h3><p>略</p><h3 id="重采样" tabindex="-1">重采样 <a class="header-anchor" href="#重采样" aria-label="Permalink to &quot;重采样&quot;">​</a></h3><p>同样的如果我们不缓存音频文件，那么就在读取后重采样，显然读取几次就需要重采样几次。除非我们在数据集准备的时候就统一重采样。</p><h3 id="增强" tabindex="-1">增强 <a class="header-anchor" href="#增强" aria-label="Permalink to &quot;增强&quot;">​</a></h3><p>必然在读取后进行。问题在于是逐条增强还是对整个批次统一增强，后者并行度更高，但前提是增强方式可以并行化。</p><h3 id="混合" tabindex="-1">混合 <a class="header-anchor" href="#混合" aria-label="Permalink to &quot;混合&quot;">​</a></h3><p>这一步理应在读取之前就计划好，相当于我们需要根据数据集的元数据（即每个样本的时长或者整个数据集的时长）来决定每轮需要不同数据集的采样比例。</p><p>根据这些步骤，我们需要设计相对应的 <code>Dataset</code> 类来实现不同功能，可能需要抽象出特定的包装类来实现不同层次的功能。例如为每个特定的数据集设计一个专门的 <code>Dataset</code> 类来实现读取（因为文件夹结构和文件格式不同），然后再设计一个通用的 <code>Dataset</code> 类来实现分段、补零、重采样、增强和混合等统一功能。</p><h1 id="lhotse" tabindex="-1">Lhotse <a class="header-anchor" href="#lhotse" aria-label="Permalink to &quot;Lhotse&quot;">​</a></h1><p>我们发现，原来社区早已开发出一套完善的语音数据集处理工具 <a href="https://github.com/lhotse-speech/lhotse/" target="_blank" rel="noreferrer">Lhotse</a></p><p>下面我们来学习一下 Lhotse 的设计理念和使用方法。</p><h2 id="清单-manifest" tabindex="-1">清单 Manifest <a class="header-anchor" href="#清单-manifest" aria-label="Permalink to &quot;清单 Manifest&quot;">​</a></h2><h3 id="两大基本清单-录音-recording-和标注-supervision" tabindex="-1">两大基本清单：录音 recording 和标注 supervision <a class="header-anchor" href="#两大基本清单-录音-recording-和标注-supervision" aria-label="Permalink to &quot;两大基本清单：录音 recording 和标注 supervision&quot;">​</a></h3><p>传统的语音数据集包含了一个清单文件（manifest），其中包含了数据集中所有音频文件 recording 的路径、采样率、时长等元信息，以及每个音频文件对应的标注信息 supervision。</p><blockquote><p>部分数据集可能并不显式提供清单文件，但是这些信息总是可以从数据集本身获得，无非多一步预处理。</p></blockquote><p>整个数据集的 manifest 包含了 <code>RecordingSet</code> 和 <code>SupervisionSet</code> 两个部分。而每个部分又由每条音频对应的 <code>Recording</code> 和 <code>Supervision</code> 组成，这两者是数据条目层级的 manifest。</p><p>我们可以通过 <code>prepare_&lt;dataset&gt;</code> 方法，来生成某个数据集的 manifest。一个具体的数据集的 manifest 可能由不同子集的 manifest 组成，表示成字典格式： 例如 <code>libri=prepare_librispeech(dataset_parts=&quot;mini_librispeech&quot;)</code> 返回的 manifest 是：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">{</span></span>
<span class="line"><span style="color:#2AA198;">&#39;train-clean-5&#39;</span><span style="color:#839496;">: {</span></span>
<span class="line"><span style="color:#2AA198;">    &#39;recordings&#39;</span><span style="color:#839496;">: RecordingSet(len</span><span style="color:#859900;">=</span><span style="color:#D33682;">1519</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#2AA198;">    &#39;supervisions&#39;</span><span style="color:#839496;">: SupervisionSet(len</span><span style="color:#859900;">=</span><span style="color:#D33682;">1519</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">    },</span></span>
<span class="line"><span style="color:#2AA198;">&#39;dev-clean-2&#39;</span><span style="color:#839496;">: {</span></span>
<span class="line"><span style="color:#2AA198;">    &#39;recordings&#39;</span><span style="color:#839496;">: RecordingSet(len</span><span style="color:#859900;">=</span><span style="color:#D33682;">1089</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#2AA198;">    &#39;supervisions&#39;</span><span style="color:#839496;">: SupervisionSet(len</span><span style="color:#859900;">=</span><span style="color:#D33682;">1089</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">    }</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre></div><blockquote><p>如果 lhotse 没有提供某个数据集的 <code>prepare_&lt;dataset&gt;</code> 方法，就需要自己实现。</p></blockquote><p>RecordingSet 和 SupervisionSet 既可以用数字索引也可以用键索引访问。我们选择训练集中的一条样本来看：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> train_set </span><span style="color:#859900;">=</span><span style="color:#839496;"> libri[</span><span style="color:#2AA198;">&#39;train-clean-5&#39;</span><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> recordings </span><span style="color:#859900;">=</span><span style="color:#839496;"> train_set[</span><span style="color:#2AA198;">&#39;recordings&#39;</span><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> supervisions </span><span style="color:#859900;">=</span><span style="color:#839496;"> train_set[</span><span style="color:#2AA198;">&#39;supervisions&#39;</span><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> recordings[</span><span style="color:#D33682;">0</span><span style="color:#839496;">] </span><span style="color:#586E75;font-style:italic;"># or recordings[&#39;1898-145715-0000&#39;]</span></span>
<span class="line"><span style="color:#839496;">Recording(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;1898-145715-0000&#39;</span><span style="color:#839496;">, sources</span><span style="color:#859900;">=</span><span style="color:#839496;">[AudioSource(type</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;file&#39;</span><span style="color:#839496;">, channels</span><span style="color:#859900;">=</span><span style="color:#839496;">[</span><span style="color:#D33682;">0</span><span style="color:#839496;">], source</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;data/LibriSpeech/train-clean-5/1898/145715/1898-145715-0000.flac&#39;</span><span style="color:#839496;">)], sampling_rate</span><span style="color:#859900;">=</span><span style="color:#D33682;">16000</span><span style="color:#839496;">, num_samples</span><span style="color:#859900;">=</span><span style="color:#D33682;">227760</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">14.235</span><span style="color:#839496;">, channel_ids</span><span style="color:#859900;">=</span><span style="color:#839496;">[</span><span style="color:#D33682;">0</span><span style="color:#839496;">], transforms</span><span style="color:#859900;">=</span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> supervisions[</span><span style="color:#D33682;">0</span><span style="color:#839496;">] </span><span style="color:#586E75;font-style:italic;"># or supervisions[&#39;1898-145715-0000&#39;]</span></span>
<span class="line"><span style="color:#839496;">SupervisionSegment(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;1898-145715-0000&#39;</span><span style="color:#839496;">, recording_id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;1898-145715-0000&#39;</span><span style="color:#839496;">, start</span><span style="color:#859900;">=</span><span style="color:#D33682;">0.0</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">14.235</span><span style="color:#839496;">, channel</span><span style="color:#859900;">=</span><span style="color:#D33682;">0</span><span style="color:#839496;">, text</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;ONCE THERE LIVED A KING WHO HAD NO CHILDREN FOR MANY YEARS AFTER HIS MARRIAGE AT LENGTH HEAVEN GRANTED HIM A DAUGHTER OF SUCH REMARKABLE BEAUTY THAT HE COULD THINK OF NO NAME SO APPROPRIATE FOR HER AS FAIRER THAN A FAIRY&#39;</span><span style="color:#839496;">, language</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;English&#39;</span><span style="color:#839496;">, speaker</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;1898&#39;</span><span style="color:#839496;">, gender</span><span style="color:#859900;">=</span><span style="color:#B58900;">None</span><span style="color:#839496;">, custom</span><span style="color:#859900;">=</span><span style="color:#B58900;">None</span><span style="color:#839496;">, alignment</span><span style="color:#859900;">=</span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span></code></pre></div><p>可以看到，<code>Recording</code> 和 <code>SupervisionSegment</code> 都是一个 <code>dataclass</code>，其中 <code>Recording</code> 包含了音频文件的路径、采样率、时长等信息，而 <code>SupervisionSegment</code> 包含了标注信息，如文本、说话人等。</p><p>注意区分 <code>Recording</code> 和 <code>AudioSource</code>，前者是一个清单对象，仅包含音频文件的元信息，而后者是一个清单对象的属性，包含了音频文件的来源信息，如文件路径、通道等。</p><p>为简便起见，以下我们统称 <code>Recording</code> 和 <code>SupervisionSegment</code> 为清单类而 <code>RecordingSet</code> 和 <code>SupervisionSet</code> 为清单集合类。</p><h4 id="加载" tabindex="-1">加载 <a class="header-anchor" href="#加载" aria-label="Permalink to &quot;加载&quot;">​</a></h4><p>清单类可以使用 <code>from_file</code>方法从音频文件或标注文件生成清单对象。 清单集合类可以使用 <code>from_dir</code> 批量加载某个目录下的所有音频文件，生成一个对象。也可以使用 <code>from_jsonl</code> 等方法从保存的 jsonl 文件中加载清单集合对象。</p><h4 id="保存" tabindex="-1">保存 <a class="header-anchor" href="#保存" aria-label="Permalink to &quot;保存&quot;">​</a></h4><p>清单类可以使用 <code>to_dict</code> 方法将一个清单对象转换为字典格式。清单集合类可以使用 <code>to_dicts</code> 方法将整个清单集合转换为字典列表格式。 清单集合类可以使用 <code>to_jsonl</code> 方法将整个清单集合保存为 jsonl 文件。</p><h4 id="处理" tabindex="-1">处理 <a class="header-anchor" href="#处理" aria-label="Permalink to &quot;处理&quot;">​</a></h4><p>清单集合类提供了以下方法来处理清单集合中的清单对象：</p><ul><li><code>filter(func)</code> ：过滤清单集合中的清单对象。</li><li><code>subset()</code>: 从清单集合中选择一个子集。</li><li><code>split()</code>: 将清单集合拆分为多个子集。</li><li><code>shuffle()</code>: 打乱清单集合中的清单对象。</li></ul><h4 id="增强-1" tabindex="-1">增强 <a class="header-anchor" href="#增强-1" aria-label="Permalink to &quot;增强&quot;">​</a></h4><p>RecordingSet 提供了惰性数据增强或变换功能：</p><ul><li><code>perturb_speed()</code></li><li><code>perturb_volume()</code></li><li><code>reverb_rir()</code></li><li><code>resample()</code></li></ul><h3 id="特征清单" tabindex="-1">特征清单 <a class="header-anchor" href="#特征清单" aria-label="Permalink to &quot;特征清单&quot;">​</a></h3><p>在语音处理任务中，我们经常需要提取各种音频特征。提取的特征除了传统的 Mel 谱、MFCC 以外，还包括各种深度学习模型提取的特征，而后者往往耗费大量计算资源，在多轮训练中反复提取显然是一种浪费，因此需要提前提取并保存这些特征。那么这些特征就类似于数据集中的音频文件和标注信息一样，需要提供一个清单类来管理这些特征。</p><p>Lhotse 的官方文档中对这部分的介绍不够详细，以下内容参照源码的 docstring。</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div><h3 id="将音频和标注信息组合起来" tabindex="-1">将音频和标注信息组合起来 <a class="header-anchor" href="#将音频和标注信息组合起来" aria-label="Permalink to &quot;将音频和标注信息组合起来&quot;">​</a></h3><h4 id="cut-和-cutset" tabindex="-1">Cut 和 CutSet <a class="header-anchor" href="#cut-和-cutset" aria-label="Permalink to &quot;Cut 和 CutSet&quot;">​</a></h4><p>以上提到的清单类并没有涉及到它们之间的相互作用。在实际应用中，我们需要将音频文件和标注信息组合起来，形成一个完整的数据样本。这对应着 <code>Cut</code>。<code>Cut</code> 是 Lhotse 进行数据处理的核心类，它是一个清单类的包装类，包含了一个 <code>Recording</code> 和若干个 <code>SupervisionSegment</code>，表示一个音频文件和它的若干标注信息。Cut 的设计理念是将音频文件和标注信息绑定在一起。类似的 Cut 可以挂载不同的特征清单类。</p><p>例如：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> rec </span><span style="color:#859900;">=</span><span style="color:#839496;"> Recording(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;rec1&#39;</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">10.0</span><span style="color:#839496;">, sampling_rate</span><span style="color:#859900;">=</span><span style="color:#D33682;">8000</span><span style="color:#839496;">, num_samples</span><span style="color:#859900;">=</span><span style="color:#D33682;">80000</span><span style="color:#839496;">, sources</span><span style="color:#859900;">=</span><span style="color:#839496;">[</span><span style="color:#CB4B16;">...</span><span style="color:#839496;">])</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> sups </span><span style="color:#859900;">=</span><span style="color:#839496;"> [</span></span>
<span class="line"><span style="color:#839496;">    SupervisionSegment(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;sup1&#39;</span><span style="color:#839496;">, recording_id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;rec1&#39;</span><span style="color:#839496;">, start</span><span style="color:#859900;">=</span><span style="color:#D33682;">0</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">3.37</span><span style="color:#839496;">, text</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;Hey, Matt!&#39;</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    SupervisionSegment(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;sup2&#39;</span><span style="color:#839496;">, recording_id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;rec1&#39;</span><span style="color:#839496;">, start</span><span style="color:#859900;">=</span><span style="color:#D33682;">4.5</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">0.9</span><span style="color:#839496;">, text</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;Yes?&#39;</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    SupervisionSegment(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;sup3&#39;</span><span style="color:#839496;">, recording_id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;rec1&#39;</span><span style="color:#839496;">, start</span><span style="color:#859900;">=</span><span style="color:#D33682;">6.9</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">2.9</span><span style="color:#839496;">, text</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;Oh, nothing&#39;</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cut </span><span style="color:#859900;">=</span><span style="color:#839496;"> MonoCut(id</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;rec1-cut1&#39;</span><span style="color:#839496;">, start</span><span style="color:#859900;">=</span><span style="color:#D33682;">0.0</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">6.0</span><span style="color:#839496;">, channel</span><span style="color:#859900;">=</span><span style="color:#D33682;">0</span><span style="color:#839496;">, recording</span><span style="color:#859900;">=</span><span style="color:#839496;">rec,</span></span>
<span class="line"><span style="color:#839496;">    supervisions</span><span style="color:#859900;">=</span><span style="color:#839496;">[sups[</span><span style="color:#D33682;">0</span><span style="color:#839496;">], sups[</span><span style="color:#D33682;">1</span><span style="color:#839496;">]])</span></span></code></pre></div><p>这里，<code>cut</code> 的 <code>start</code> 和 <code>duration</code> 表示了这个 Cut 在底层 <code>Recording</code> 中的起始时间和持续时间。</p><p>在给定了清单以后，上述的 <code>Cut</code> 是可以通过 <code>CutSet</code> 自动生成的。一个 <code>CutSet</code> 可以从清单中自动生成：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cuts </span><span style="color:#859900;">=</span><span style="color:#839496;"> CutSet.from_manifests(recordings</span><span style="color:#859900;">=</span><span style="color:#839496;">my_recording_set)</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cuts2 </span><span style="color:#859900;">=</span><span style="color:#839496;"> CutSet.from_manifests(features</span><span style="color:#859900;">=</span><span style="color:#839496;">my_feature_set)</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cuts3 </span><span style="color:#859900;">=</span><span style="color:#839496;"> CutSet.from_manifests(</span></span>
<span class="line"><span style="color:#839496;">    recordings</span><span style="color:#859900;">=</span><span style="color:#839496;">my_recording_set,</span></span>
<span class="line"><span style="color:#839496;">    features</span><span style="color:#859900;">=</span><span style="color:#839496;">my_feature_set,</span></span>
<span class="line"><span style="color:#839496;">    supervisions</span><span style="color:#859900;">=</span><span style="color:#839496;">my_supervision_set,</span></span>
<span class="line"><span style="color:#839496;">)</span></span></code></pre></div><p>注意 <code>CutSet</code> 的创建可以是惰性的或立即执行的。</p><p>从清单中自动生成的 <code>CutSet</code> 中的 cuts 默认与传入的录音或特征相同，这并不适合训练。我们可以将这些片段转换为更短的片段，例如：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cuts_A </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.trim_to_supervisions()</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cuts_B </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.cut_into_windows(duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">5.0</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">&gt;&gt;&gt;</span><span style="color:#839496;"> cuts_C </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.trim_to_unsupervised_segments()</span></span></code></pre></div><h4 id="处理-1" tabindex="-1">处理 <a class="header-anchor" href="#处理-1" aria-label="Permalink to &quot;处理&quot;">​</a></h4><p><code>Cut</code> 提供了以下方法来处理 <code>Cut</code> 对象，注意每种变换都会返回一个新的 <code>Cut</code> 对象，而不会修改原来的 <code>Cut</code> 对象，也不会修改底层的音频、特征、标注。这些变换总是在<code>load_audio</code>或<code>load_features</code>时按需进行的。</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">cut_2_to_4s </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.truncate(offset</span><span style="color:#859900;">=</span><span style="color:#D33682;">2</span><span style="color:#839496;">, duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">2</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cut_padded </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.pad(duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">10.0</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cut_extended </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.extend_by(duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">5.0</span><span style="color:#839496;">, direction</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;both&#39;</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cut_mixed </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.mix(other_cut, offset_other_by</span><span style="color:#859900;">=</span><span style="color:#D33682;">5.0</span><span style="color:#839496;">, snr</span><span style="color:#859900;">=</span><span style="color:#D33682;">20</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cut_append </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.append(other_cut)</span></span>
<span class="line"><span style="color:#839496;">cut_24k </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.resample(</span><span style="color:#D33682;">24000</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cut_sp </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.perturb_speed(</span><span style="color:#D33682;">1.1</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cut_vp </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.perturb_volume(</span><span style="color:#D33682;">2</span><span style="color:#839496;">.)</span></span>
<span class="line"><span style="color:#839496;">cut_rvb </span><span style="color:#859900;">=</span><span style="color:#839496;"> cut.reverb_rir(rir_recording)</span></span></code></pre></div><p><code>CutSet</code> 也提供了类似的方法，同样它们也不会修改原来的 <code>CutSet</code> 对象，而是返回一个新的 <code>CutSet</code> 对象。</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">longer_than_5s </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.filter(</span><span style="color:#93A1A1;font-weight:bold;">lambda</span><span style="color:#839496;"> c: c.duration </span><span style="color:#859900;">&gt;</span><span style="color:#D33682;"> 5</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">first_100 </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.subset(first</span><span style="color:#859900;">=</span><span style="color:#D33682;">100</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">split_into_4 </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.split(num_splits</span><span style="color:#859900;">=</span><span style="color:#D33682;">4</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">shuffled </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.shuffle()</span></span>
<span class="line"><span style="color:#839496;">random_sample </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.sample(n_cuts</span><span style="color:#859900;">=</span><span style="color:#D33682;">10</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">new_ids </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.modify_ids(</span><span style="color:#93A1A1;font-weight:bold;">lambda</span><span style="color:#839496;"> c: c.id </span><span style="color:#859900;">+</span><span style="color:#2AA198;"> &#39;-newid&#39;</span><span style="color:#839496;">)</span></span></code></pre></div><p>以下是数据增强的方法：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">cuts_sp </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.perturb_speed(factor</span><span style="color:#859900;">=</span><span style="color:#D33682;">1.1</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cuts_vp </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.perturb_volume(factor</span><span style="color:#859900;">=</span><span style="color:#D33682;">2</span><span style="color:#839496;">.)</span></span>
<span class="line"><span style="color:#839496;">cuts_24k </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.resample(</span><span style="color:#D33682;">24000</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">cuts_rvb </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.reverb_rir(rir_recordings)</span></span></code></pre></div><blockquote><p>注意如果 <code>CutSet</code> 包含了特征清单，那么它们会在数据增强后自动分离。</p></blockquote><p>以下变换可以批量进行：</p><div class="language-py"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">cuts </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.pad(num_frames</span><span style="color:#859900;">=</span><span style="color:#D33682;">300</span><span style="color:#839496;">)  </span><span style="color:#586E75;font-style:italic;"># or duration=30.0</span></span>
<span class="line"><span style="color:#839496;">cuts </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.truncate(max_duration</span><span style="color:#859900;">=</span><span style="color:#D33682;">30.0</span><span style="color:#839496;">, offset_type</span><span style="color:#859900;">=</span><span style="color:#2AA198;">&#39;start&#39;</span><span style="color:#839496;">)  </span><span style="color:#586E75;font-style:italic;"># truncate from start to 30.0s</span></span>
<span class="line"><span style="color:#839496;">cuts </span><span style="color:#859900;">=</span><span style="color:#839496;"> cuts.mix(other_cuts, snr</span><span style="color:#859900;">=</span><span style="color:#839496;">[</span><span style="color:#D33682;">10</span><span style="color:#839496;">, </span><span style="color:#D33682;">30</span><span style="color:#839496;">], mix_prob</span><span style="color:#859900;">=</span><span style="color:#D33682;">0.5</span><span style="color:#839496;">)</span></span></code></pre></div>`,68)]))}const h=a(p,[["render",e]]);export{u as __pageData,h as default};
